    line=[name or '/',typ,str(shape),dtype,json.dumps(attrs(obj),ensure_ascii=True,sort_keys=True)]
    lines.append('\t'.join(line))
lines=[]
with h5py.File(path,'r') as f:
    f.visititems(visit)
